#include "AudioHistory.h"
static void testAudioHistory(const File& root,Assets& assets){
    AudioHistory history;HistoryOptions options;AudioHistorySnapshot snapshot;
    expect(!history.active()&&history.frames()==0&&history.bytes()==0,"input history is off and retains no samples by default");
    auto prefs=root.getChildFile("history-settings.json");options={15,4,InputMode::second};
    expect(saveHistoryOptions(prefs,options).wasOk(),"audio history settings save locally");HistoryOptions read;
    expect(loadHistoryOptions(prefs,read).wasOk()&&read==options&&!JSON::parse(prefs).hasProperty("enabled"),"history preferences remember source and budget, never enabled state");
    prefs.replaceWithText("{\"schema\":1,\"seconds\":1,\"memoryMiB\":4,\"mode\":0}");
    expect(loadHistoryOptions(prefs,read).failed()&&read==options,"invalid preferences reject without replacing prior settings");
    Array<var> cases;bool all=true;
    for(double rate:{8000.,44100.,48000.,96000.,192000.})for(auto mode:{InputMode::stereo,InputMode::first,InputMode::second})for(int seconds:{15,30,60})for(int memory:{4,16,32,64}){
        HistoryOptions o{seconds,memory,mode};auto valid=history.start(rate,o);int channels=mode==InputMode::stereo?2:1;
        bool ok=valid.wasOk()&&history.active()&&history.frames()==0&&history.capacity()==(int)jmin(rate*seconds,(double)memory*1048576/(channels*4))&&history.bytes()<=(uint64_t)memory*1048576;
        expect(ok,"every supported rate/source/duration/budget preallocates a bounded callback ring");all&=ok;auto* row=new DynamicObject();row->setProperty("rate",rate);row->setProperty("mode",(int)mode);row->setProperty("seconds",seconds);row->setProperty("memoryMiB",memory);row->setProperty("frames",history.capacity());row->setProperty("passed",ok);cases.add(var(row));
    }
    expect(history.start(0,options).failed()&&history.start(384000,options).failed()&&history.start(48000,{1,4,InputMode::stereo}).failed(),"unsupported rates and budgets cannot configure input capture");history.disable();
    AudioBuffer<float> raw(2,4096);auto fill=[&](int first){for(int i=0;i<4096;++i){raw.setSample(0,i,(first+i)*.00001f);raw.setSample(1,i,-(first+i)*.00002f);}};
    history.start(8000,{15,4,InputMode::stereo});int total=0;
    for(int block=0;block<35;++block){fill(total);history.capture(raw,2,{4+total/4000.,120,8000,4096,17,true});total+=4096;}
    expect(history.frames()==120000&&history.copyFrozen(snapshot).failed(),"live ring wraps to its duration and must be frozen before copy");history.pause();
    expect(history.copyFrozen(snapshot).wasOk()&&snapshot.audio.getNumSamples()==120000&&snapshot.revision==17&&std::abs(snapshot.firstBeat-(4+(total-120000)/4000.))<1e-7&&std::abs(snapshot.endBeat-(4+total/4000.))<1e-7,"frozen history retains exact chronological Song range after ring wrap");
    bool exact=true;for(int i=0;i<120000;++i){exact&=snapshot.audio.getSample(0,i)==(total-120000+i)*.00001f;exact&=snapshot.audio.getSample(1,i)==-(total-120000+i)*.00002f;}expect(exact,"wrapped stereo history preserves every raw float including amplitudes above unity");
    history.capture(raw,2,{100,120,8000,4096,18,true});expect(history.frames()==120000,"paused history retains old input without accepting new samples");
    std::atomic<bool> cancel{true};auto previous=snapshot.audio.getSample(0,0);expect(history.copyFrozen(snapshot,&cancel).failed()&&snapshot.audio.getSample(0,0)==previous,"cancelled copy leaves prior snapshot intact");
    for(auto mode:{InputMode::first,InputMode::second}){history.start(48000,{15,4,mode});raw.clear();raw.setSample(0,0,.25f);raw.setSample(1,0,-.125f);history.capture(raw,2,{4,120,48000,4096,7,true});history.pause();expect(history.copyFrozen(snapshot).wasOk()&&snapshot.audio.getNumChannels()==1&&snapshot.audio.getSample(0,0)==(mode==InputMode::first?.25f:-.125f),"mono capture uses the explicitly selected physical input");}
    for(auto mode:{InputMode::stereo,InputMode::second}){history.start(48000,{15,4,mode});history.capture(raw,1,{4,120,48000,4096,7,true});expect(history.frames()==0,"stereo and second-input capture reject missing physical channels");}
    history.start(48000,{15,4,InputMode::stereo});raw.clear();raw.setSample(0,0,std::numeric_limits<float>::quiet_NaN());raw.setSample(1,1,std::numeric_limits<float>::infinity());raw.setSample(0,2,1.25f);history.capture(raw,2,{4,120,48000,4096,7,true});history.pause();history.copyFrozen(snapshot);expect(snapshot.invalidSamples==2&&snapshot.audio.getSample(0,0)==0&&snapshot.audio.getSample(1,1)==0&&snapshot.audio.getSample(0,2)==1.25f,"nonfinite input sanitizes safely without normalizing finite samples");
    auto folder=root.getChildFile("history-save-"+Uuid().toString());HistorySaveTask task(history,folder);task.run();
    expect(task.done.load()&&task.result.wasOk()&&task.hash==SHA256(folder.getChildFile("input.wav")).toHexString(),"frozen input worker publishes a byte-verified float WAV and source hash");
    auto meta=JSON::parse(folder.getChildFile("capture.json"));expect((int)meta["frames"]==4096&&(int)meta["channels"]==2&&(int)meta["revision"]==7&&(double)meta["firstBeat"]==4&&meta["sha256"].toString()==task.hash,"provenance includes source, frames, rate, tempo, Song beat, revision and hash");
    HistorySaveTask occupied(history,folder);occupied.run();expect(occupied.result.failed()&&task.hash==SHA256(folder.getChildFile("input.wav")).toHexString(),"freeze refuses to replace an existing preview folder");
    HistorySaveTask cancelled(history,root.getChildFile("history-cancel-"+Uuid().toString()));cancelled.cancel=true;cancelled.run();expect(cancelled.result.failed()&&!cancelled.folder.exists(),"cancel before freeze creates no retained disk copy");
    auto project=emptyProject();project.bpm=120;Project next;auto original=JSON::toString(projectToJson(project));
    expect(appendAudioHistory(project,snapshot,folder.getChildFile("input.wav"),7,next).wasOk()&&next.clips.back().isAudio()&&next.clips.back().beat==4&&std::abs(next.clips.back().length-4096/24000.)<1e-7&&JSON::toString(projectToJson(project))==original,"history placement inserts a dry audio clip at captured beat without changing its source project");
    auto sentinel=JSON::toString(projectToJson(next));project.bpm=100;expect(appendAudioHistory(project,snapshot,folder.getChildFile("input.wav"),7,next).failed()&&JSON::toString(projectToJson(next))==sentinel,"tempo-mismatched history cannot silently change musical alignment");project.bpm=120;project.tracks[7].isBus=true;expect(appendAudioHistory(project,snapshot,folder.getChildFile("input.wav"),7,next).failed(),"history cannot be assigned to a bus");project.tracks[7].isBus=false;project.clips.resize(maxClips);expect(appendAudioHistory(project,snapshot,folder.getChildFile("input.wav"),7,next).failed(),"full arrangement rejects history atomically");
    history.start(48000,{15,4,InputMode::stereo});raw.clear();HistorySpan span{4,120,48000,1024,1,true};history.capture(raw,2,span);span.firstBeat+=1024/24000.;history.capture(raw,2,span);expect(history.frames()==2048,"contiguous blocks accumulate in the current revision");
    for(int reason=0;reason<4;++reason){if(reason==0)span.firstBeat=10;if(reason==1)++span.revision;if(reason==2)span.bpm=100;if(reason==3){auto gap=span;gap.valid=false;history.capture(raw,2,gap);}history.capture(raw,2,span);expect(history.frames()==1024,"seek, revision, tempo and omitted blocks start separate history segments");span.firstBeat+=1024*span.bpm/(60*48000);}
    history.capture(raw,2,{0,120,44100,1024,1,true});history.pause();expect(!history.active()&&history.invalidated()&&history.copyFrozen(snapshot).failed(),"device rate change disarms stale history until an explicit fresh start");history.start(48000,{15,4,InputMode::first});expect(!history.invalidated(),"explicit start clears a previous device discontinuity");
    std::atomic<bool> producerDone{false};std::thread producer([&]{double beat=0;while(!producerDone.load()){history.capture(raw,2,{beat,120,48000,1024,1,true});beat+=1024/24000.;}});Thread::sleep(5);history.pause();bool frozen=history.copyFrozen(snapshot).wasOk();producerDone=true;producer.join();expect(frozen&&snapshot.audio.getNumSamples()>0,"freeze synchronizes a live producer and returns a coherent immutable snapshot");history.disable();expect(!history.active()&&history.bytes()==0&&history.frames()==0,"Off closes retention and releases ring memory");
    auto song=emptyProject();song.songMode=true;song.loop=false;auto engine=makeEngine(song,assets,root);engine->seekRequested=4;AudioBuffer<float> out(2,512);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);auto actual=engine->historySpan;
    expect(actual.valid&&actual.firstBeat==4&&actual.bpm==song.bpm&&actual.rate==48000&&actual.frames==512,"Engine tags exact complete Song callback input time after a seek");engine->stop();engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"stopped transport is excluded from retrospective capture");song.songMode=false;engine=makeEngine(song,assets,root);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"PAT playback cannot invent an arrangement placement");
    song.songMode=true;song.loop=true;song.markers.push_back({"range","Range",4,5,1});song.loopSection="range";engine=makeEngine(song,assets,root);engine->seekRequested=4.99;engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"callback crossing a loop wrap is excluded instead of being misaligned");
    song.loop=false;song.loopSection.clear();song.markers.clear();engine=makeEngine(song,assets,root);engine->seekRequested=song.songLength()-.001;engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"partial callback at natural Song end is excluded from history");
    engine=makeEngine(song,assets,root);Sample preview;preview.audio.setSize(2,512);preview.audio.clear();preview.sampleRate=48000;engine->preview(&preview,0,0,.5f);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"sample-preview callback is excluded even while Song is playing");
    engine=makeEngine(song,assets,root);Engine::TakePlan take;take.startBeat=0;take.gateBeat=0;take.endBeat=8;engine->beginTake(take);engine->render(out.getWritePointer(0),out.getWritePointer(1),512);expect(!engine->historySpan.valid,"scheduled take callback is excluded from retrospective memory");
    auto before=historyFileStamp(folder.getChildFile("input.wav"));auto time=folder.getChildFile("input.wav").getLastModificationTime();auto file=folder.getChildFile("input.wav");MemoryBlock bytes;file.loadFileAsData(bytes);if(bytes.getSize()>100){static_cast<char*>(bytes.getData())[bytes.getSize()-1]^=1;file.replaceWithData(bytes.getData(),bytes.getSize());file.setLastModificationTime(time);}expect(historyFileStamp(file)!=before,"history fingerprint detects preview replacement even with unchanged file size and timestamp");
    auto* report=new DynamicObject();report->setProperty("version","0.75.0");report->setProperty("passed",all);report->setProperty("cases",cases);root.getChildFile("history-evaluation.json").replaceWithText(JSON::toString(var(report),false));
}

